const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('ko-KR')+'만원';
function read(k,f){try{return JSON.parse(localStorage.getItem('cydemo-'+k))??f}catch{return f}}
function save(k,v){try{localStorage.setItem('cydemo-'+k,JSON.stringify(v))}catch{}}
const state={user:read('user',null),diagnosis:read('diagnosis',null),step:0,answers:{age:'30대',head:'세대주',marriage:'신혼',region:'서울',ownership:'무주택',years:3,family:1,children:'없음',account:4,payments:48,income:'직접 확인할게요',assets:10000,wish:'경기',type:'공공분양'},filterRegion:'전체',filterType:'전체',search:'',sort:'default',finance:'대출',messages:[]};
const icons={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',check:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="m8 10 2 2 5-5M8 16h8"/>',money:'<rect x="3" y="5" width="18" height="14" rx="3"/><circle cx="12" cy="12" r="3"/><path d="M6 12h.1M18 12h.1"/>',chat:'<path d="M20 15a3 3 0 0 1-3 3H9l-5 3V6a3 3 0 0 1 3-3h10a3 3 0 0 1 3 3z"/><path d="M8 9h8M8 13h5"/>',leaf:'<path d="M19 3C9 3 4 8 5 14s8 8 12 2c2-3 2-8 2-13Z"/><path d="M4 21 15 9"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',card:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M3 10h18M7 15h4"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>'};
const icon=(name,warm=false)=>`<span class="icon ${warm?'orange-icon':''}"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.home}</svg></span>`;
const houses=[]; // 서버에서 받은 공고를 모아 두는 곳 (live.js가 채운다)
function building(h){return `<svg viewBox="0 0 400 210" preserveAspectRatio="xMidYMid slice" aria-label="${esc(h.name)} 단지 일러스트" role="img"><rect width="400" height="210" fill="${h.color}"/><circle cx="322" cy="44" r="25" fill="#f8f3dc" opacity=".85"/><path d="M0 156Q90 113 180 160T400 145V210H0Z" fill="#829d7f" opacity=".4"/><rect x="65" y="55" width="88" height="145" fill="#f2f0e3"/><rect x="160" y="85" width="82" height="115" fill="#e8e5d6"/><rect x="249" y="30" width="81" height="170" fill="#f9f7ed"/><path d="M153 55v145h-16V55M242 85v115h-15V85M330 30v170h-14V30" fill="#bcc3ae"/>${[80,105,130,175,200,265,289].map((x,i)=>[75,100,125,150,175].filter(y=>y>(i>4?45:i>2?90:60)).map(y=>`<rect x="${x}" y="${y}" width="11" height="12" rx="1" fill="#728b80" opacity=".65"/>`).join('')).join('')}<rect y="195" width="400" height="15" fill="#8eaa80"/><path d="M19 199v-29M366 199v-35" stroke="#57745a" stroke-width="5"/><circle cx="19" cy="162" r="22" fill="#7b966e"/><circle cx="368" cy="157" r="28" fill="#668b6b"/></svg>`}
function go(route){closeModal();if(location.hash==='#'+route){render();window.scrollTo(0,0)}else location.hash=route}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function closeModal(){$('#modal-root').innerHTML=''}
let modalPreviousFocus;
function modal(html,large=false){modalPreviousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-label="안내" class="modal ${large?'large':''}"><button class="modal-close" data-action="close" aria-label="닫기">×</button>${html}</section></div>`;$('.modal button, .modal input')?.focus()}
function header(route){const links=[['diagnosis','청약 진단'],['homes','집 찾기'],['finance','금융 정보'],['community','커뮤니티']];$('#header').innerHTML=`<div class="nav"><a class="brand" href="#home">청약돼<span>?!</span></a><nav class="nav-links" aria-label="주요 메뉴">${links.map(([id,t])=>`<a href="#${id}" class="${route.startsWith(id)||(id==='homes'&&route.startsWith('detail'))?'active':''}">${t}</a>`).join('')}<a href="#dashboard" class="${['dashboard','saved','report','profile'].includes(route)?'active':''}">내 공간</a></nav><div class="nav-account">${state.user?.member?`<button data-action="logout">로그아웃</button><a class="pill" href="#dashboard">${esc(state.user.name)}님</a>`:'<button class="pill" data-action="signup">로그인</button>'}</div></div>`}
function home(){return `<section class="hero"><div class="hero-image"></div><div class="hero-body"><div class="eyebrow"><span class="dot"></span> YOUR HOME, YOUR NEXT CHAPTER</div><h1>내 집을 찾는 일,<br><em>내 조건부터</em> 시작해요.</h1><p>흩어진 청약 공고부터 주거 자금까지.<br>지금 나에게 필요한 정보를 한곳에서 만나보세요.</p><div class="hero-actions"><a class="btn orange" href="#diagnosis">1분 진단 시작하기 <span>↗</span></a><a href="#homes" class="hero-link">공고 먼저 둘러보기</a></div><div class="hero-help"><span>✓ 가입 없이 결과 확인</span><span>✓ 원할 때만 로그인</span></div></div><span class="hero-label">A PLACE TO CALL YOUR OWN</span></section><div class="wrap"><div class="quick-bar">${[['check','청약 진단','내 조건을 차근차근','diagnosis'],['home','집 찾기','청약·임대 공고 한눈에','homes'],['money','금융 정보','내 생활에 맞는 자금 계획','finance'],['chat','우리 이야기','함께 나누는 주거·금융생활','community']].map(([i,t,p,r])=>`<a class="quick" href="#${r}">${icon(i,i==='chat')}<div><strong>${t}</strong><small>${p}</small></div></a>`).join('')}</div><section class="section"><div class="section-head"><div><div class="eyebrow">FIND YOUR PLACE</div><h2>다음 시작을 기다리는 집</h2><p>지금 접수 중인 공고예요. 공고를 눌러 상세 정보를 확인해 보세요.</p></div><a href="#homes" class="text-link">공고 전체 보기 ↗</a></div><div class="grid3">${featuredHouses().map(h=>houseCard(h)).join('')}</div></section><section class="feature-strip"><div class="feature-panel"><div><span class="badge">금융생활</span><h3>집은 찾았는데,<br>자금은 얼마나 필요할까요?</h3><p>내 자금과 필요한 비용을 함께 정리해요.</p><a href="#finance/budget">자금 계획 계산해 보기 ↗</a></div><div class="feature-number">₩</div></div><div class="feature-panel warm"><div><span class="badge orange-badge">시작 가이드</span><h3>처음이라 더 복잡한 청약,<br>하나씩 알아가면 돼요.</h3><p>내 조건을 정리하고 확인할 항목을 찾아요.</p><a href="#diagnosis">내 조건 알아보기 ↗</a></div><div class="feature-number" style="color:#dfc3a9">01</div></div></section><section class="community-preview"><div class="community-intro">${icon('chat',true)}<h3>혼자 고민하지 말고,<br>우리끼리 이야기해요.</h3><p>주거, 금융생활, 커리어까지<br>비슷한 관심사를 가진 사람들과.</p><a href="#community" class="text-link">커뮤니티 둘러보기 ↗</a></div><div>${state.posts.slice(0,4).map(p=>`<a href="#post/${p.id}" class="mini-post"><span class="badge gray">${p.board}</span><span class="post-name">${esc(p.title)}</span><small>♡ ${p.likes}</small></a>`).join('')}</div></section></div>`}
const stages=['기본 정보','주택 소유','가족 구성','청약통장','소득·자산','희망 조건'];
const REGIONS=['서울','부산','대구','인천','광주','대전','울산','세종','경기','강원','충북','충남','전북','전남','경북','경남','제주'];
function regionSelect(key,values,selected,label){return `<select aria-label="${label}" data-region-answer="${key}">${values.map(v=>`<option ${v===selected?'selected':''}>${v}</option>`).join('')}</select>`}
function options(key,values){return `<div class="options">${values.map(v=>`<button class="option ${state.answers[key]===v?'selected':''}" data-action="answer" data-key="${key}" data-value="${v}">${v}</button>`).join('')}</div>`}
function diagnosis(){const a=state.answers;const contents=[`<div class="field"><label>연령대</label>${options('age',['20대','30대','40대 이상'])}</div><div class="field"><label>세대주 여부</label>${options('head',['세대주','세대원','잘 모르겠어요'])}</div><div class="field"><label>혼인 상태</label>${options('marriage',['미혼','신혼','기혼'])}</div><div class="field"><label>현재 거주 지역</label>${regionSelect('region',REGIONS,a.region,'현재 거주 지역 선택')}</div>`,`<div class="field"><label>세대의 주택 소유 상태</label>${options('ownership',['무주택','주택 보유','확인 필요'])}<small>실제 진단에서는 세대 구성원의 소유 이력 확인이 필요합니다.</small></div><div class="field"><label for="years">무주택 기간 · 년</label><input id="years" type="number" min="0" max="30" value="${a.years}" data-answer="years"><small>정확한 산정 시작일은 공고 기준으로 별도 확인합니다.</small></div>`,`<div class="field"><label for="family">부양가족 수 · 본인 제외</label><input id="family" type="number" min="0" max="6" value="${a.family}" data-answer="family"></div><div class="field"><label>미성년 자녀</label>${options('children',['없음','1명','2명 이상'])}</div><div class="callout">가족의 이름이나 주민등록번호는 입력하지 않습니다. 숫자와 조건만 입력해요.</div>`,`<div class="field"><label for="account">청약통장 가입 기간 · 년</label><input id="account" type="number" min="0" max="30" value="${a.account}" data-answer="account"></div><div class="field"><label for="payments">납입 인정 회차</label><input id="payments" type="number" min="0" max="500" value="${a.payments}" data-answer="payments"><small>실제 인정 회차는 은행에서 확인한 값을 사용합니다.</small></div>`,`<div class="field"><label>소득 기준 확인 상태</label>${options('income',['확인했어요','직접 확인할게요','아직 모르겠어요'])}<small>소득은 입력받지 않아요. 소득 기준은 공고문에서 직접 확인해 주세요.</small></div><div class="field"><label for="assets">주거에 쓸 수 있는 현금 · 만원</label><input id="assets" type="number" min="0" max="1000000" step="100" value="${a.assets}" data-answer="assets"><small>대략적인 금액을 입력해 주세요.</small></div>`,`<div class="field"><label>희망 지역</label>${regionSelect('wish',['전체',...REGIONS],a.wish,'희망 지역 선택')}</div><div class="field"><label>관심 주거 유형</label>${options('type',['공공분양','민간분양','공공임대','전체'])}</div><div class="callout">결과에서는 선택한 지역·유형과 연결된 공고를 보여드려요. 최종 신청 자격을 확정하는 기능은 제공하지 않습니다.</div>`];return `<div class="diagnosis-wrap reveal"><div class="diagnosis-head"><div class="eyebrow" style="justify-content:center">GET TO KNOW YOUR CONDITIONS</div><h1>내 집 찾기, 내 조건부터.</h1><p>6단계로 내 조건을 정리해 보세요. 결과는 서버가 계산해 드려요.</p></div><div class="stepper">${stages.map((s,i)=>`<button data-action="step" data-id="${i}" class="${i===state.step?'current':i<state.step?'done':''}"><span>${i<state.step?'✓':i+1}</span>${s}</button>`).join('')}</div><div class="progress"><div style="width:${(state.step+1)/6*100}%"></div></div><div class="diagnosis-body"><section class="panel diagnosis-panel"><div class="step-count">STEP 0${state.step+1} / 06</div><h2>${stages[state.step]}</h2><p class="description">내 조건을 알면, 필요한 정보를 더 쉽게 찾을 수 있어요.</p>${contents[state.step]}<div class="step-actions"><button class="btn secondary" data-action="previous" ${state.step===0?'disabled':''}>이전</button><button class="btn" data-action="next">${state.step===5?'진단 결과 보기':'다음'} →</button></div></section><aside class="diagnosis-aside"><h3>이렇게 이어져요</h3><p>입력한 조건은 추천 이유와<br>확인할 항목을 정리하는 데 사용해요.</p><div class="flow-mini"><div>01 내 조건 입력 <span>지금</span></div><div>02 결과 미리보기 <span>가입 없이</span></div><div>03 추천 공고 확인 <span>서버 계산</span></div><div>04 공고·자금 탐색 <span>자유롭게</span></div></div><p>입력한 조건은 추천 계산을 위해 서버에 저장돼요.</p></aside></div></div>`}
function emptyPage(title,desc,route,label){return `<div class="wrap page"><div class="empty">${icon('home')}<h3>${title}</h3><p>${desc}</p><a href="#${route}" class="btn">${label}</a></div></div>`}
function render(){const raw=location.hash.slice(1)||'home';const [route,arg,id]=raw.split('/');header(route);let html;switch(route){case'diagnosis':html=diagnosis();break;case'result':html=result();break;case'homes':html=homes();break;case'detail':html=detail(arg);break;case'dashboard':html=dashboard();break;case'saved':html=savedPage();break;case'finance':html=finance(decodeURIComponent(arg||''),id);break;case'community':html=community();break;case'post':html=post(arg);break;case'chat':html=chat(arg);break;case'report':html=report();break;case'profile':html=profile();break;case'preferences':html=preferencesPage();break;default:html=home()}$('#app').innerHTML=html;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action,id=Number(b.dataset.id),v=b.dataset.value;switch(act){case'close':closeModal();modalPreviousFocus?.focus();break;case'guide':guide();break;case'guide-go':go(v);break;case'step':state.step=id;render();break;case'answer':state.answers[b.dataset.key]=v;render();break;case'previous':if(state.step>0){state.step--;render()}break;case'next':if(state.step<5){state.step++;render();window.scrollTo(0,0)}else{state.diagnosis={...state.answers};save('diagnosis',state.diagnosis);go('result')}break;case'scroll-section':e.preventDefault();$('#'+b.dataset.target)?.scrollIntoView({behavior:'smooth'});break;case'finance-tab':state.finance=v;go('finance');break;case'prompt':answerChat(v,id);break;case'print':window.print();break;case'delete-diagnosis':state.diagnosis=null;save('diagnosis',null);render();toast('이 브라우저의 진단 정보를 삭제했어요.');break;case'reset':modal('<h2>이 브라우저의 저장 정보를 초기화할까요?</h2><p>현재 브라우저의 로그인 정보와 진단 정보가 초기화됩니다. 서버에 저장된 정보는 지워지지 않아요.</p><button class="btn full" data-action="reset-confirm">초기화</button>');break;case'reset-confirm':Object.keys(localStorage).filter(k=>k.startsWith('cydemo-')).forEach(k=>localStorage.removeItem(k));location.hash='home';location.reload();break;}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.regionAnswer){state.answers[el.dataset.regionAnswer]=el.value;return}if(el.dataset.answer){state.answers[el.dataset.answer]=Math.max(Number(el.min||0),Math.min(Number(el.max||1e9),Number(el.value)||0));el.value=state.answers[el.dataset.answer]}if(el.dataset.filter){state[el.dataset.filter]=el.value;render()}if(el.id==='budget-house'){const h=houses.find(x=>x.id===Number(el.value));if(h)$('#budget-cost').value=h.price;calcBudget()}if(['budget-cost','budget-cash'].includes(el.id))calcBudget();if(el.id==='chat-house'){state.messages=[];go('chat/'+el.value)}});
function calcBudget(){const cost=Number($('#budget-cost').value)||0,cash=Number($('#budget-cash').value)||0;$('#budget-output').textContent=money(Math.max(0,cost-cash))}
document.addEventListener('submit',e=>{const form=e.target;e.preventDefault();switch(form.id){case'budget-form':calcBudget();toast('단순 차액을 계산했어요.');break;case'chat-form':answerChat(form.querySelector('input').value.trim(),form.dataset.id);break;}});
document.addEventListener('keydown',e=>{const dialog=$('.modal');if(!dialog)return;if(e.key==='Escape'){closeModal();modalPreviousFocus?.focus()}if(e.key==='Tab'){const nodes=[...dialog.querySelectorAll('button,a,input,textarea,select')].filter(n=>!n.disabled);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
// 첫 화면은 live.js 끝에서 그린다 (공고 데이터 연결 함수가 먼저 정의돼야 해서)
